using System;

// PROGRAM: Eksperimen Parameter Modifier ref, out, dan in
public struct BigPayload
{
    public long A, B, C, D; // 32 byte data
}

public class ParameterDemonstrator
{
    // 1. Modifier OUT: Wajib mengisi nilai sebelum selesai
    public static bool TryBagi(int pembilang, int penyebut, out int hasil, out int sisa)
    {
        if (penyebut == 0)
        {
            hasil = 0;
            sisa = 0;
            return false;
        }

        hasil = pembilang / penyebut;
        sisa = pembilang % penyebut;
        return true;
    }

    // 2. Modifier REF: Memodifikasi langsung variabel pemanggil
    public static void GandakanSaldo(ref decimal saldo)
    {
        saldo *= 2;
    }

    // 3. Modifier IN: Mengoper referensi read-only tanpa alokasi penyalinan
    public static long JumlahkanPayload(in BigPayload payload)
    {
        // payload.A = 100; // ERROR: Tidak boleh diubah karena readonly!
        return payload.A + payload.B + payload.C + payload.D;
    }
}

public class Program
{
    public static void Main()
    {
        // Uji Out
        if (ParameterDemonstrator.TryBagi(17, 5, out int div, out int rem))
        {
            Console.WriteLine($"17 / 5 = {div} sisa {rem}");
        }

        // Uji Ref
        decimal myBalance = 1_000_000m;
        ParameterDemonstrator.GandakanSaldo(ref myBalance);
        Console.WriteLine($"Saldo setelah digandakan: Rp {myBalance:N0}");
    }
}

