using System;
using System.Text;

public class AccountValidator
{
    public static bool TryParseAccountNumber(string? input, out string formattedAccount)
    {
        formattedAccount = "";
        if (string.IsNullOrWhiteSpace(input)) return false;

        var sb = new StringBuilder();
        foreach (char c in input)
        {
            if (char.IsWhiteSpace(c) || c == '-') continue;
            if (!char.IsDigit(c)) return false;
            sb.Append(c);
        }

        if (sb.Length != 10) return false;

        formattedAccount = $"ACC-{sb}";
        return true;
    }

    public static void Main()
    {
        if (TryParseAccountNumber("123-456-7890", out string acc1))
        {
            Console.WriteLine($"Valid: {acc1}");
        }
        else
        {
            Console.WriteLine("Invalid");
        }
    }
}
